import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC08%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E6%95%B4%E5%90%88%E7%AE%A1%E7%90%86/8.3%20%E6%95%B4%E4%BD%93%E5%8F%98%E6%9B%B4%E6%8E%A7%E5%88%B6.html","title":"8.3 整体变更控制","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第08章 项目整合管理/8.3 整体变更控制.md"}`),a={name:`8.3 整体变更控制.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_8-3-整体变更控制" tabindex="-1"><a class="header-anchor" href="#_8-3-整体变更控制"><span>8.3 整体变更控制</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>整体变更控制是指对项目变更进行识别、评估、审批、实施和验证的过程，确保变更有序进行，避免对项目目标造成不利影响。</p><h2 id="变更控制流程" tabindex="-1"><a class="header-anchor" href="#变更控制流程"><span>变更控制流程</span></a></h2><h3 id="_1-变更请求提交" tabindex="-1"><a class="header-anchor" href="#_1-变更请求提交"><span>1. 变更请求提交</span></a></h3><ul><li><strong>来源</strong>：项目团队、客户、管理层等</li><li><strong>形式</strong>：书面形式，填写变更请求表</li><li><strong>内容</strong>：变更描述、变更原因、变更影响</li></ul><h3 id="_2-变更评估" tabindex="-1"><a class="header-anchor" href="#_2-变更评估"><span>2. 变更评估</span></a></h3><ul><li><strong>评估内容</strong>：技术可行性、成本影响、进度影响、质量影响</li><li><strong>评估主体</strong>：变更控制委员会（CCB）</li><li><strong>输出</strong>：变更评估报告</li></ul><h3 id="_3-变更审批" tabindex="-1"><a class="header-anchor" href="#_3-变更审批"><span>3. 变更审批</span></a></h3><ul><li><strong>审批主体</strong>：变更控制委员会（CCB）</li><li><strong>审批结果</strong>：批准、否决、推迟</li><li><strong>审批依据</strong>：变更评估报告、项目目标</li></ul><h3 id="_4-变更实施" tabindex="-1"><a class="header-anchor" href="#_4-变更实施"><span>4. 变更实施</span></a></h3><ul><li><strong>实施主体</strong>：项目团队</li><li><strong>实施要求</strong>：按照批准的变更方案执行</li><li><strong>记录</strong>：记录变更实施情况</li></ul><h3 id="_5-变更验证" tabindex="-1"><a class="header-anchor" href="#_5-变更验证"><span>5. 变更验证</span></a></h3><ul><li><strong>验证内容</strong>：变更是否按计划实施</li><li><strong>验证主体</strong>：项目经理或质量保证人员</li><li><strong>输出</strong>：变更验证报告</li></ul><h3 id="_6-变更记录" tabindex="-1"><a class="header-anchor" href="#_6-变更记录"><span>6. 变更记录</span></a></h3><ul><li><strong>记录内容</strong>：变更请求、评估结果、审批意见、实施情况</li><li><strong>记录目的</strong>：便于追溯和审计</li></ul><h2 id="变更控制委员会-ccb" tabindex="-1"><a class="header-anchor" href="#变更控制委员会-ccb"><span>变更控制委员会（CCB）</span></a></h2><h3 id="组成" tabindex="-1"><a class="header-anchor" href="#组成"><span>组成</span></a></h3><ul><li>项目经理</li><li>项目发起人</li><li>关键干系人</li><li>技术专家</li></ul><h3 id="职责" tabindex="-1"><a class="header-anchor" href="#职责"><span>职责</span></a></h3><ul><li>评审变更请求</li><li>审批变更请求</li><li>监督变更实施</li></ul><h2 id="变更管理的重要性" tabindex="-1"><a class="header-anchor" href="#变更管理的重要性"><span>变更管理的重要性</span></a></h2><h3 id="控制项目风险" tabindex="-1"><a class="header-anchor" href="#控制项目风险"><span>控制项目风险</span></a></h3><ul><li>避免未经授权的变更</li><li>减少变更带来的风险</li></ul><h3 id="保证项目目标" tabindex="-1"><a class="header-anchor" href="#保证项目目标"><span>保证项目目标</span></a></h3><ul><li>确保变更符合项目目标</li><li>避免范围蔓延</li></ul><h3 id="提高项目可控性" tabindex="-1"><a class="header-anchor" href="#提高项目可控性"><span>提高项目可控性</span></a></h3><ul><li>使变更过程规范化</li><li>提高项目管理的可控性</li></ul><h2 id="常见变更类型" tabindex="-1"><a class="header-anchor" href="#常见变更类型"><span>常见变更类型</span></a></h2><h3 id="范围变更" tabindex="-1"><a class="header-anchor" href="#范围变更"><span>范围变更</span></a></h3><ul><li>增加或减少项目范围</li><li>调整项目交付物</li></ul><h3 id="进度变更" tabindex="-1"><a class="header-anchor" href="#进度变更"><span>进度变更</span></a></h3><ul><li>调整项目进度计划</li><li>延长或缩短工期</li></ul><h3 id="成本变更" tabindex="-1"><a class="header-anchor" href="#成本变更"><span>成本变更</span></a></h3><ul><li>调整项目预算</li><li>增加或减少成本</li></ul><h3 id="质量变更" tabindex="-1"><a class="header-anchor" href="#质量变更"><span>质量变更</span></a></h3><ul><li>调整质量标准</li><li>改变质量要求</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>变更控制流程</strong></li><li><strong>变更控制委员会的职责</strong></li><li><strong>变更管理的重要性</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>提交评估审批实施验证记录，变更控制六步骤</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：变更控制流程的第一步是什么？ A. 变更评估 B. 变更请求提交 C. 变更审批 D. 变更实施</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：变更控制流程依次是：变更请求提交、变更评估、变更审批、变更实施、变更验证、变更记录。第一步是变更请求提交。</p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};